@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderService orderService;

    public OrderController(OrderService orderService) {
        this.orderService = orderService;
    }

    @GetMapping("/{id}")
    public ResponseEntity<Order> getOrder(
            @PathVariable Long id,
            @RequestHeader("Authorization") String token) { // Stateless: auth in every request
        var order = orderService.findById(id);
        return ResponseEntity.ok()
            .cacheControl(CacheControl.maxAge(60, TimeUnit.SECONDS)) // Cacheable constraint
            .eTag(String.valueOf(order.version())) // Cache validation support
            .body(order); // Uniform Interface: standard JSON representation
    }

    @PostMapping
    public ResponseEntity<Order> createOrder(
            @RequestBody OrderRequest request,
            @RequestHeader("Authorization") String token) { // No session, token carries identity
        var newOrder = orderService.create(request);
        return ResponseEntity.created(
            URI.create("/api/orders/" + newOrder.id()) // Resource identification
        ).body(newOrder);
    }
}

@RestController
@RequestMapping("/api/users")
public class UserController {
    private final JwtService jwtService;
    private final UserRepository userRepository;

    @GetMapping("/profile")
    public ResponseEntity<UserProfile> getProfile(
            @RequestHeader("Authorization") String authHeader) {
        // Extract token from "Bearer <token>" format
        var token = authHeader.substring(7);
        var userId = jwtService.extractUserId(token); // Token contains user ID

        // No session lookup needed, token is self-contained
        var user = userRepository.findById(userId)
            .orElseThrow(() -> new UserNotFoundException(userId));

        return ResponseEntity.ok(new UserProfile(
            user.id(),
            user.name(),
            user.email()
        ));
    }

    @PostMapping("/settings")
    public ResponseEntity<Void> updateSettings(
            @RequestHeader("Authorization") String authHeader,
            @RequestBody SettingsRequest settings) {
        var token = authHeader.substring(7);
        var userId = jwtService.extractUserId(token); // Same token, new request, no session
        userRepository.updateSettings(userId, settings);
        return ResponseEntity.noContent().build();
    }
}

@Configuration
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/public/**").permitAll()
                .anyRequest().authenticated()
            )
            // Trust X-Forwarded headers from API Gateway layer
            .csrf(csrf -> csrf.disable())
            .sessionManagement(session -> 
                session.sessionCreationPolicy(SessionCreationPolicy.STATELESS)
            );
        return http.build();
    }
}

@RestController
public class OrderController {

    @GetMapping("/api/orders/{id}")
    public ResponseEntity<Order> getOrder(
            @PathVariable Long id,
            @RequestHeader("X-Forwarded-For") String clientIp, // Set by API Gateway layer
            @RequestHeader("X-Request-Id") String requestId) { // Added by load balancer

        // Server doesn't know about intermediate layers
        // It trusts X-Forwarded headers from trusted proxies
        log.info("Request {} from {} for order {}", requestId, clientIp, id);

        var order = orderService.findById(id);
        return ResponseEntity.ok(order);
    }
}

@RestController
@RequestMapping("/api/products")
public class ProductController {
    private final ProductService productService;

    @GetMapping("/{id}")
    public ResponseEntity<Product> getProduct(@PathVariable Long id) {
        var product = productService.findById(id);

        // Cache for 5 minutes, public means CDNs can cache it
        return ResponseEntity.ok()
            .cacheControl(CacheControl.maxAge(5, TimeUnit.MINUTES).cachePublic())
            .eTag(String.valueOf(product.version())) // Version-based cache validation
            .body(product);
    }

    @GetMapping("/{id}/detailed")
    public ResponseEntity<Product> getDetailedProduct(
            @PathVariable Long id,
            @RequestHeader(value = "If-None-Match", required = false) String clientETag) {

        var product = productService.findById(id);
        var currentETag = String.valueOf(product.version());

        // Client sent ETag, check if resource changed
        if (currentETag.equals(clientETag)) {
            return ResponseEntity.status(HttpStatus.NOT_MODIFIED)
                .eTag(currentETag)
                .build(); // 304 response, no body sent
        }

        return ResponseEntity.ok()
            .cacheControl(CacheControl.maxAge(10, TimeUnit.MINUTES).cachePrivate()) // User-specific, no CDN caching
            .eTag(currentETag)
            .lastModified(product.updatedAt())
            .body(product);
    }
}

@RestController
@RequestMapping("/api/orders")
public class OrderController {

    @GetMapping("/{id}")
    public ResponseEntity<OrderResponse> getOrder(@PathVariable Long id) {
        var order = orderService.findById(id);

        // Resource identified by URI: /api/orders/123
        var response = new OrderResponse(
            order.id(),
            order.status(),
            order.totalAmount(),
            // HATEOAS: include links to available actions
            buildLinks(order)
        );

        // Self-descriptive message: Content-Type tells client how to parse
        return ResponseEntity.ok()
            .contentType(MediaType.APPLICATION_JSON)
            .body(response);
    }

    private List<Link> buildLinks(Order order) {
        var links = new ArrayList<Link>();
        links.add(new Link("/api/orders/" + order.id(), "self"));

        if (order.status() == OrderStatus.PENDING) {
            // Dynamic links based on resource state
            links.add(new Link("/api/orders/" + order.id() + "/cancel", "cancel"));
            links.add(new Link("/api/orders/" + order.id() + "/confirm", "confirm"));
        }
        return links;
    }
}

record OrderResponse(Long id, OrderStatus status, BigDecimal total, List<Link> links) {}
record Link(String href, String rel) {}
